        // Verify our balance increased
        uint256 balance = IERC20(TARGET).balanceOf(address(this));
        console.log("Our balance after mint:", balance);
        assertGt(balance, 0, "Balance should be greater than 0");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

